1	import Foundation
2	
3	// MARK: - Camera log (spec §11 GR-16)
4	
5	/// A maker's published log curve, as `media.color.log` spells it. Apple
6	/// Log 2 is Apple Log's curve with Apple Wide Gamut (GR-16's append); Canon
7	/// Log 2 and 3 pair with Cinema Gamut or BT.2020 (spec §11 HD-17).
8	enum LogCurve: String, Codable, CaseIterable {
9	    case appleLog = "apple_log", slog3, vlog, appleLog2 = "apple_log2"
10	    case canonLog2 = "canon_log2", canonLog3 = "canon_log3"
11	
12	    /// The gamuts the curve pairs with, its default first — the core's
13	    /// `LogCurve::gamuts`, which refuses any other.
14	    var gamuts: [CameraGamut] {
15	        switch self {
16	        case .appleLog: return [.bt2020]
17	        case .appleLog2: return [.appleWideGamut]
18	        case .slog3: return [.sGamut3Cine, .sGamut3]
19	        case .vlog: return [.vGamut]
20	        case .canonLog2, .canonLog3: return [.cinemaGamut, .bt2020]
21	        }
22	    }
23	
24	    var displayName: String {
25	        switch self {
26	        case .appleLog: return "Apple Log"
27	        case .appleLog2: return "Apple Log 2"
28	        case .slog3: return "S-Log3"
29	        case .vlog: return "V-Log"
30	        // "C-Log": "Canon Log 3 / Cinema Gamut" is wider than the popup (HD-17 (b)).
31	        case .canonLog2: return "C-Log2"
32	        case .canonLog3: return "C-Log3"
33	        }
34	    }
35	}
36	
37	/// The camera gamut a log curve's signal is in, as `media.color.gamut`
38	/// spells it.
39	enum CameraGamut: String, Codable, CaseIterable {
40	    case bt2020, sGamut3Cine = "s_gamut3_cine", sGamut3 = "s_gamut3", vGamut = "v_gamut"
41	    case appleWideGamut = "apple_wide_gamut"
42	    case cinemaGamut = "cinema_gamut"
43	
44	    var displayName: String {
45	        switch self {
46	        case .bt2020: return "BT.2020"
47	        case .sGamut3Cine: return "S-Gamut3.Cine"
48	        case .sGamut3: return "S-Gamut3"
49	        case .vGamut: return "V-Gamut"
50	        case .appleWideGamut: return "Apple Wide Gamut"
51	        case .cinemaGamut: return "Cinema Gamut"
52	        }
53	    }
54	}
55	
56	// MARK: - The PQ peak (spec §11 HD-12)
57	
58	/// Which HDR10 field gave a PQ file's peak, as `media.color.pq.from` spells
59	/// it: CTA-861.3's MaxCLL, or SMPTE ST 2086's mastering maximum.
60	enum PeakSource: String, Codable, CaseIterable {
61	    case maxCLL = "max_cll", masteringDisplay = "mastering_display"
62	}
63	
64	/// A PQ file's HDR10 peak, `media.color.pq`: `file`, what import read in
65	/// whole cd/m², with `from` naming its field; `peak`, the person's override.
66	/// The core wrote it, so it decodes leniently (`init(from:)` below).
67	struct PQColor: Codable, Equatable {
68	    var file: UInt32?
69	    var from: PeakSource?
70	    var peak: UInt32?
71	
72	    /// The peak step 0 uses: the override, else the file's; nil means
73	    /// `InputConversions.pqWhite`.
74	    var effectivePeak: UInt32? { peak ?? file }
75	
76	    /// The stored shape, each key only when set.
77	    var dictionary: [String: Any] {
78	        var d: [String: Any] = [:]
79	        if let file = file { d["file"] = file }
80	        if let from = from { d["from"] = from.rawValue }
81	        if let peak = peak { d["peak"] = peak }
82	        return d
83	    }
84	}
85	
86	extension PQColor {
87	    init(from decoder: Decoder) throws {
88	        let c = try decoder.container(keyedBy: CodingKeys.self)
89	        self.init(file: c.lenient(.file), from: c.lenient(.from), peak: c.lenient(.peak))
90	    }
91	}
92	
93	// MARK: - The media's colour
94	
95	/// A video media's Camera Log: a built-in curve and its gamut, or a `lut`
96	/// media converting the file instead; `detected` when import read it from
97	/// the file's label; `pq` a PQ file's peak (spec §11 HD-12). Also a recipe
98	/// layer's and a plan segment's `input`, which carry no `detected` and no
99	/// `pq` but a flat `peak` (the effective one) — so the decoder is written
100	/// out: a synthesized one would throw on the absent key, and `lenient` would
101	/// read that as no setting at all.
102	struct MediaColor: Codable, Equatable {
103	    var log: LogCurve?
104	    var gamut: CameraGamut?
105	    var lut: UInt32?
106	    var detected: Bool
107	    /// The stored peak record; nil on every media that is not a PQ file.
108	    var pq: PQColor?
109	    /// An `input`'s effective PQ peak; never stored.
110	    var peak: UInt32?
111	
112	    init(log: LogCurve? = nil, gamut: CameraGamut? = nil, lut: UInt32? = nil,
113	         detected: Bool = false, pq: PQColor? = nil, peak: UInt32? = nil) {
114	        self.log = log
115	        self.gamut = gamut
116	        self.lut = lut
117	        self.detected = detected
118	        self.pq = pq
119	        self.peak = peak
120	    }
121	
122	    init(from decoder: Decoder) throws {
123	        let c = try decoder.container(keyedBy: CodingKeys.self)
124	        log = c.lenient(.log)
125	        gamut = c.lenient(.gamut)
126	        lut = c.lenient(.lut)
127	        detected = c.lenient(.detected, false)
128	        pq = c.lenient(.pq)
129	        peak = c.lenient(.peak)
130	    }
131	
132	    /// The gamut step 0 converts from: the stored one, else the curve's
133	    /// first (the core stores it so; a hand-written file may not).
134	    var effectiveGamut: CameraGamut? {
135	        gamut ?? log?.gamuts.first
136	    }
137	
138	    /// `set_media_color`'s `color`: `log`, `gamut`, `lut` and the override
139	    /// `pq.peak` as `peak` (spec §11 HD-12), never `detected` or the file's
140	    /// reading, which only import writes.
141	    var opDictionary: [String: Any] {
142	        var d: [String: Any] = [:]
143	        if let log = log { d["log"] = log.rawValue }
144	        if let gamut = gamut { d["gamut"] = gamut.rawValue }
145	        if let lut = lut { d["lut"] = lut }
146	        if let peak = pq?.peak { d["peak"] = peak }
147	        return d
148	    }
149	
150	    /// An `add_media` descriptor's `color`: `log`, `gamut`, `lut`,
151	    /// `detected` when true and `pq` whole — never a flat `peak`.
152	    var descriptorDictionary: [String: Any] {
153	        var d: [String: Any] = [:]
154	        if let log = log { d["log"] = log.rawValue }
155	        if let gamut = gamut { d["gamut"] = gamut.rawValue }
156	        if let lut = lut { d["lut"] = lut }
157	        if detected { d["detected"] = true }
158	        if let pq = pq { d["pq"] = pq.dictionary }
159	        return d
160	    }
161	}
