1	import AVFoundation
2	import CoreMedia
3	import CoreVideo
4	
5	extension MediaImporter {
6	    private static let appleLogLabel = kCMFormatDescriptionLogTransferFunction_AppleLog as String
7	    private static let appleLog2Label = REDACTED as String
8	
9	    /// The Camera Log a video track's label names (spec §11 GR-16), read
10	    /// when `probeAsset` runs: Apple Log (`com.apple.rec2020.apple-log`,
11	    /// `kCMFormatDescriptionLogTransferFunction_AppleLog`) with BT.2020, or
12	    /// Apple Log 2 (`REDACTED`, whose file
13	    /// carries the same extension key) with Apple Wide Gamut, each
14	    /// `detected`; nil for any other label or none. S-Log3 and V-Log carry no
15	    /// label AVFoundation reads, so they are chosen by hand.
16	    static func detectedColor(_ descriptions: [CMFormatDescription]) -> MediaColor? {
17	        for description in descriptions {
18	            let label = CMFormatDescriptionGetExtension(
19	                description, extensionKey: kCMFormatDescriptionExtension_LogTransferFunction)
20	                as? String
21	            if label == Self.appleLogLabel {
22	                return MediaColor(log: .appleLog, gamut: .bt2020, detected: true)
23	            }
24	            if label == Self.appleLog2Label {
25	                return MediaColor(log: .appleLog2, gamut: .appleWideGamut, detected: true)
26	            }
27	        }
28	        return nil
29	    }
30	
31	    /// A PQ video track's HDR10 peak (spec §11 HD-12, HD-18), read when
32	    /// `probeAsset` runs: `{pq}` for a track whose description
33	    /// `InputConversion` reads as PQ — the core's reading of the
34	    /// description's mastering-display and content-light extensions, else,
35	    /// for an `av01` track, of its `av1C` record's and first sample's
36	    /// metadata OBUs, and for an `hvc1` or `hev1` track of the first sample's
37	    /// SEI (`firstSample`) — `{pq: {}}` when none reads; nil for any track
38	    /// that is not PQ. Synchronous (spec §11 W-8).
39	    static func detectedPQ(
40	        _ descriptions: [CMFormatDescription], track: AVAssetTrack, asset: AVAsset
41	    ) -> MediaColor? {
42	        guard let description = descriptions.first(where: {
43	            if case .pq = InputConversion.choose(for: $0) { return true }
44	            return false
45	        }) else { return nil }
46	        func data(_ key: CFString) -> Data? {
47	            CMFormatDescriptionGetExtension(description, extensionKey: key) as? Data
48	        }
49	        let mastering = data(kCMFormatDescriptionExtension_MasteringDisplayColorVolume)
50	        let contentLight = data(kCMFormatDescriptionExtension_ContentLightLevelInfo)
51	        if mastering == nil, contentLight == nil,
52	            CMFormatDescriptionGetMediaSubType(description) == kCMVideoCodecType_AV1
53	        {
54	            let atoms = CMFormatDescriptionGetExtension(
55	                description,
56	                extensionKey: kCMFormatDescriptionExtension_SampleDescriptionExtensionAtoms)
57	                as? [String: Any]
58	            let read = ReelHDR10.av1Peak(
59	                config: atoms?["av1C"] as? Data, sample: firstSample(of: track, in: asset))
60	            return MediaColor(pq: read)
61	        }
62	        var sample: Data?
63	        var nalLength = 0
64	        if mastering == nil, contentLight == nil, let length = hevcNALLength(description) {
65	            nalLength = length
66	            sample = firstSample(of: track, in: asset)
67	        }
68	        let read = ReelHDR10.peak(
69	            mastering: mastering, contentLight: contentLight, sample: sample, nalLength: nalLength)
70	        return MediaColor(pq: read)
71	    }
72	
73	    /// A PQ still's HDR10 peak (spec §11 HD-20 (b)), read when `probeImage`
74	    /// runs: `{pq}` for a still whose decoded space is PQ-based
75	    /// (`StillColor.conversion(at:)` answers `.pq`) — the core's reading of
76	    /// the file's bytes, a PNG's `cLLI`/`mDCV` or a HEIF or AVIF primary
77	    /// item's `clli`/`mdcv` — `{pq: {}}` when none reads; nil for any other
78	    /// still. ImageIO's properties are not read. Synchronous (spec §11 W-8).
79	    static func detectedStillPQ(_ url: URL) -> MediaColor? {
80	        guard case .pq = StillColor.conversion(at: url) else { return nil }
81	        let file = try? Data(contentsOf: url, options: .alwaysMapped)
82	        return MediaColor(pq: ReelHDR10.stillPeak(file: file))
83	    }
84	
85	    /// An HEVC description's NAL length size (its `hvcC`'s), nil for any
86	    /// other codec or an unreadable record.
87	    private static func hevcNALLength(_ description: CMFormatDescription) -> Int? {
88	        let subtype = CMFormatDescriptionGetMediaSubType(description)
89	        // 'hvc1' and 'hev1' (whose parameter sets may sit in the stream too).
90	        guard subtype == kCMVideoCodecType_HEVC || subtype == FourCharCode(0x6865_7631)
91	        else { return nil }
92	        var length: Int32 = 0
93	        let status = CMVideoFormatDescriptionGetHEVCParameterSetAtIndex(
94	            description, parameterSetIndex: 0, parameterSetPointerOut: nil,
95	            parameterSetSizeOut: nil, parameterSetCountOut: nil, nalUnitHeaderLengthOut: &length)
96	        return status == noErr && length > 0 ? Int(length) : nil
97	    }
98	
99	    /// The bytes of the track's first sample with data, read unconverted
100	    /// (`outputSettings: nil`): an x265 track's first buffer holds no sample,
101	    /// so empty buffers are skipped. The reader is cancelled once it has one.
102	    private static func firstSample(of track: AVAssetTrack, in asset: AVAsset) -> Data? {
103	        guard let reader = try? AVAssetReader(asset: asset) else { return nil }
104	        let output = AVAssetReaderTrackOutput(track: track, outputSettings: nil)
105	        output.alwaysCopiesSampleData = false
106	        guard reader.canAdd(output) else { return nil }
107	        reader.add(output)
108	        defer { reader.cancelReading() }
109	        guard reader.startReading() else { return nil }
110	        while let buffer = output.copyNextSampleBuffer() {
111	            guard let block = CMSampleBufferGetDataBuffer(buffer) else { continue }
112	            let length = CMBlockBufferGetDataLength(block)
113	            guard length > 0 else { continue }
114	            var bytes = Data(count: length)
115	            let status = bytes.withUnsafeMutableBytes { out -> OSStatus in
116	                guard let base = out.baseAddress else { return -1 }
117	                return CMBlockBufferCopyDataBytes(
118	                    block, atOffset: 0, dataLength: length, destination: base)
119	            }
120	            return status == noErr ? bytes : nil
121	        }
122	        return nil
123	    }
124	}
