57	
58	/// Which HDR10 field gave a PQ file's peak, as `media.color.pq.from` spells
59	/// it: CTA-861.3's MaxCLL, or SMPTE ST 2086's mastering maximum.
60	enum PeakSource: String, Codable, CaseIterable {
61	    case maxCLL = "max_cll", masteringDisplay = "mastering_display"
62	}
63	
64	/// A PQ file's HDR10 peak, `media.color.pq`: `file`, what import read in
65	/// whole cd/m², with `from` naming its field; `peak`, the person's override.
66	/// The core wrote it, so it decodes leniently (`init(from:)` below).
67	struct PQColor: Codable, Equatable {
68	    var file: UInt32?
69	    var from: PeakSource?
70	    var peak: UInt32?
71	
72	    /// The peak step 0 uses: the override, else the file's; nil means
73	    /// `InputConversions.pqWhite`.
74	    var effectivePeak: UInt32? { peak ?? file }
75	
76	    /// The stored shape, each key only when set.
77	    var dictionary: [String: Any] {
78	        var d: [String: Any] = [:]
79	        if let file = file { d["file"] = file }
80	        if let from = from { d["from"] = from.rawValue }
81	        if let peak = peak { d["peak"] = peak }
82	        return d
83	    }
84	}
85	
86	extension PQColor {
87	    init(from decoder: Decoder) throws {
88	        let c = try decoder.container(keyedBy: CodingKeys.self)
89	        self.init(file: c.lenient(.file), from: c.lenient(.from), peak: c.lenient(.peak))
90	    }
91	}
