1	//! Camera log on a media (spec §11 GR-16): `set_media_color`, the rules a
2	//! `media.color` obeys, and what the recipe and the plan publish of it —
3	//! written once for every door that meets it.
4	//!
5	//! - **The op.** `set_media_color {media, color}` sets a video media's
6	//!   setting, or clears it with `color: null` (an identity when there is
7	//!   none). `color` is read strictly ([`read_color`]): an object or `null`,
8	//!   only the keys `log`, `gamut`, `lut`, `peak`, `detected` and `pq`, each
9	//!   through serde's own vocabulary. `detected` and `pq` are import's to
10	//!   write, so the op refuses them; what the op stores always has `detected:
11	//!   false`, and an absent `gamut` is stored as the curve's first
12	//!   ([`LogCurve::gamuts`]). `peak` is a PQ file's override (spec §11 HD-12):
13	//!   `color` replaces the Camera Log and the override together, import's
14	//!   reading (`pq.file`, `pq.from`) survives every op, and `null` clears
15	//!   both, keeping the reading.
16	//! - **The rules** ([`Project::check_media_color`]), each its own sentence:
17	//!   the media is a video file, or an image whose colour is a PQ still's
18	//!   `pq` alone (spec §11 HD-20 (b)); the setting has `log` or `lut`, not both, or
19	//!   is a PQ file's `pq` alone; `gamut` goes with `log` and is one its curve
20	//!   takes; `lut` names a `lut` media of the project; `pq`'s peaks are within
21	//!   [`PEAK_MIN`]–[`PEAK_MAX`] and `from` goes with `file`. The op answers
22	//!   them as refusals; `add_media` (whose descriptor may carry a detected
23	//!   `color`) and `validate` (a file) as errors, as they answer every other
24	//!   field. The op's own: a `peak` only on a PQ file and in range, an image
25	//!   taking only a `peak` alone, and an asked `color` with none of `log`,
26	//!   `lut` and `peak` refused.
27	//! - **What draws** ([`Project::media_input`]): the recipe layer of a media
28	//!   or still source and the plan's video segment publish the setting as
29	//!   `input` — `{log, gamut}` or `{lut}`, and `peak` (the effective PQ peak)
30	//!   beside either or alone — and the app converts at step 0. The recipe
31	//!   layer of an image source publishes a PQ still's `{peak}` alone (spec
32	//!   §11 HD-20 (b)), and `null` for `{pq: {}}`. A `lut` that names no `lut`
33	//!   media publishes nothing of it.
34	//! - **Removing a LUT** that converts a media (`lut.rs`'s `remove_lut`) is
35	//!   refused naming those media ([`Project::media_converted_by`]), or with
36	//!   `with_clips` clears the conversions with the looks.
37	
38	use serde_json::{Map, Value};
39	
40	use crate::export::describe;
41	use crate::export_overrides::spelled;
42	use crate::model::{Media, MediaColor, MediaKind, Project};
43	use crate::model_media_color::{PqColor, PEAK_MAX, PEAK_MIN};
44	use crate::outcome::Outcome;
45	
46	/// The keys a `color` may carry: the setting's, `peak` (the op's alone), and
47	/// the two import writes, which the op refuses by name.
48	const COLOR_KEYS: [&str; 6] = ["log", "gamut", "lut", "peak", "detected", "pq"];
49	
50	/// An asked `color`: the Camera Log as the model spells it, and `peak`.
51	struct Asked {
52	    color: MediaColor,
53	    peak: Option<i64>,
54	}
55	
56	/// A media kind as a sentence names it: "an audio file", "an image", "a LUT".
57	fn kind_phrase(kind: MediaKind) -> &'static str {
58	    match kind {
59	        MediaKind::Video => "a video file",
60	        MediaKind::Audio => "an audio file",
61	        MediaKind::Image => "an image",
62	        MediaKind::Lut => "a LUT",
63	    }
64	}
65	
66	/// The sentence for a setting with nothing to convert by.
67	const NEEDS_LOG_OR_LUT: &str = "color needs log or lut; null clears it";
68	
69	/// A colour is a setting on a video file; on an image only when `image_ok`
70	/// (a PQ still's peak alone, spec §11 HD-20 (b)), and every other kind never.
71	fn check_kind(media: &Media, image_ok: bool) -> Result<(), String> {
72	    if media.kind == MediaKind::Video || (media.kind == MediaKind::Image && image_ok) {
73	        return Ok(());
74	    }
75	    Err(format!(
76	        "media {} is {}; Camera Log is a setting on a video file",
77	        media.id,
78	        kind_phrase(media.kind)
79	    ))
80	}
81	
82	/// A stored `pq` (spec §11 HD-12): `file` and `peak` within
83	/// [`PEAK_MIN`]–[`PEAK_MAX`], and `from` present exactly when `file` is.
84	fn check_pq(pq: PqColor) -> Result<(), String> {
85	    for (key, value) in [("file", pq.file), ("peak", pq.peak)] {
86	        if let Some(n) = value.filter(|n| !(PEAK_MIN..=PEAK_MAX).contains(n)) {
87	            return Err(format!(
88	                "color.pq.{key} must be {PEAK_MIN}–{PEAK_MAX} cd/m², not {n}"
89	            ));
90	        }
91	    }
92	    if pq.file.is_some() != pq.from.is_some() {
93	        return Err("color.pq.from goes with color.pq.file".to_string());
94	    }
95	    Ok(())
96	}
97	
98	/// `color` read strictly: `None` for `null`, else the setting and `peak`, or
99	/// the `Err` naming what is wrong — not an object, an unknown key, a `peak`
100	/// that is not a whole number, or a value serde refuses (its own sentence,
101	/// naming the variants).
102	fn read_color(color: &Value) -> Result<Option<Asked>, String> {
103	    let fields = match color {
104	        Value::Null => return Ok(None),
105	        Value::Object(fields) => fields,
106	        other => {
107	            return Err(format!(
108	                "color must be a json object or null, not {}",
109	                describe(other)
110	            ))
111	        }
112	    };
113	    if let Some(key) = fields
114	        .keys()
115	        .find(|key| !COLOR_KEYS.contains(&key.as_str()))
116	    {
117	        return Err(format!("unknown key \"{key}\" in color"));
118	    }
119	    let peak = match fields.get("peak") {
120	        None => None,
121	        Some(value) => Some(value.as_i64().ok_or_else(|| {
122	            format!(
123	                "color.peak must be a whole number of cd/m², not {}",
124	                describe(value)
125	            )
126	        })?),
127	    };
128	    let mut setting = fields.clone();
129	    setting.remove("peak");
130	    serde_json::from_value(Value::Object(setting))
131	        .map(|color| Some(Asked { color, peak }))
132	        .map_err(|e| format!("color does not match the schema: {e}"))
133	}
134	
135	impl Project {
136	    /// Sets or clears a video media's camera-log setting (spec §11 GR-16)
137	    /// and a PQ file's peak override (HD-12). `Err` for an unknown media or
138	    /// an unreadable `color`; a refusal, in the rule's own sentence, for
139	    /// `detected`, `pq`, a `peak` out of range or on a file that is not PQ,
140	    /// an asked `color` with none of `log`, `lut` and `peak`, or a setting
141	    /// [`Project::check_media_color`] refuses.
142	    pub(crate) fn set_media_color(&self, media: u32, color: &Value) -> Result<Outcome, String> {
143	        let current = self.require_media(media)?.color;
144	        // Import's reading, kept by every op: `pq` without the override.
145	        let reading = current
146	            .and_then(|c| c.pq)
147	            .map(|pq| PqColor { peak: None, ..pq });
148	        let stored = match read_color(color)? {
149	            None => reading.map(|pq| MediaColor {
150	                pq: Some(pq),
151	                ..MediaColor::default()
152	            }),
153	            Some(asked) => match self.asked_color(media, asked, reading) {
154	                Ok(setting) => Some(setting),
155	                Err(why) => return Ok(Outcome::Refused(why)),
156	            },
157	        };
158	        let mut next = self.clone();
159	        let Some(row) = next.media.iter_mut().find(|m| m.id == media) else {
160	            return Err(format!("no media with id {media}"));
161	        };
162	        row.color = stored;
163	        if stored.is_some() {
164	            if let Err(why) = self.check_media_color(row) {
165	                return Ok(Outcome::Refused(why));
166	            }
167	        }
168	        self.finish(next)
169	    }
170	
171	    /// The setting an asked `color` stores on `media` beside its `reading`,
172	    /// or (`Err`) the refusal in the rule's own sentence, in this order: `detected`,
173	    /// `pq`, a `peak` outside [`PEAK_MIN`]–[`PEAK_MAX`] or on media that is
174	    /// not a PQ file, the media's kind (an image passes only with a `peak`
175	    /// alone, spec §11 HD-20 (b)), and none of `log`, `lut` and `peak`.
176	    fn asked_color(
177	        &self,
178	        media: u32,
179	        asked: Asked,
180	        reading: Option<PqColor>,
181	    ) -> Result<MediaColor, String> {
182	        let given = asked.color;
183	        if given.detected {
184	            return Err("color.detected is written by import, not set".to_string());
185	        }
186	        if given.pq.is_some() {
187	            return Err("color.pq is read from the file at import, not set".to_string());
188	        }
189	        let peak = match asked.peak {
190	            None => None,
191	            Some(n) => match u32::try_from(n) {
192	                Ok(n) if (PEAK_MIN..=PEAK_MAX).contains(&n) => Some(n),
193	                _ => {
194	                    return Err(format!(
195	                        "color.peak must be {PEAK_MIN}–{PEAK_MAX} cd/m², not {n}"
196	                    ))
197	                }
198	            },
199	        };
200	        if peak.is_some() && reading.is_none() {
201	            return Err(format!(
202	                "media {media} is not a PQ file; only a PQ file takes a peak"
203	            ));
204	        }
205	        if let Some(row) = self.media(media) {
206	            let image_ok = peak.is_some()
207	                && given.log.is_none()
208	                && given.lut.is_none()
209	                && given.gamut.is_none();
210	            check_kind(row, image_ok)?;
211	        }
212	        if given.log.is_none() && given.lut.is_none() && peak.is_none() {
213	            return Err(NEEDS_LOG_OR_LUT.to_string());
214	        }
215	        let mut setting = given;
216	        if let (Some(log), None) = (setting.log, setting.gamut) {
217	            setting.gamut = log.gamuts().first().copied();
218	        }
219	        setting.pq = reading.map(|pq| PqColor { peak, ..pq });
220	        Ok(setting)
221	    }
222	
223	    /// A media's `color` against this project; `Ok` for a media without one.
224	    /// Each sentence is the rule's own, in this order: the media's kind (an
225	    /// image passes only with an import's `pq` alone, spec §11 HD-20 (b)), a
226	    /// setting with neither or both of `log` and `lut` (neither is a PQ
227	    /// file's `pq` alone, which passes), a `gamut` without a `log`, a pairing
228	    /// the curve does not take, a `lut` that is not a `lut` media of the
229	    /// project, and `pq`'s own ([`check_pq`]).
230	    pub(crate) fn check_media_color(&self, media: &Media) -> Result<(), String> {
231	        let Some(color) = media.color else {
232	            return Ok(());
233	        };
234	        let image_ok = color.pq.is_some()
235	            && !color.detected
236	            && color.log.is_none()
237	            && color.lut.is_none()
238	            && color.gamut.is_none();
239	        check_kind(media, image_ok)?;
240	        match (color.log, color.lut) {
241	            (None, None) if color.pq.is_none() || color.detected => {
242	                return Err(NEEDS_LOG_OR_LUT.to_string())
243	            }
244	            (Some(_), Some(_)) => return Err("color takes log or lut, not both".to_string()),
245	            _ => {}
246	        }
247	        if let (None, Some(_)) = (color.log, color.gamut) {
248	            return Err("color.gamut goes with log".to_string());
249	        }
250	        if let (Some(log), Some(gamut)) = (color.log, color.gamut) {
251	            if !log.gamuts().contains(&gamut) {
252	                let takes: Vec<String> = log.gamuts().iter().map(|g| spelled(*g)).collect();
253	                return Err(format!(
254	                    "{} takes gamut {}, not {}",
255	                    spelled(log),
256	                    takes.join(" or "),
257	                    spelled(gamut)
258	                ));
259	            }
260	        }
261	        if let Some(id) = color.lut {
262	            self.check_lut_reference("color.lut", id)?;
263	        }
264	        color.pq.map_or(Ok(()), check_pq)
265	    }
266	
267	    /// What step 0 converts `media` with, as the recipe layer's and the plan
268	    /// segment's `input`: `{log, gamut}` for a built-in curve (the gamut its
269	    /// first when the stored one is absent), `{lut}` naming a `lut` media of
270	    /// the project, and `peak` — a PQ file's effective peak (spec §11 HD-12)
271	    /// — beside either or alone; or `null` — no setting, no such media, or a
272	    /// `lut` that names none and no peak. A PQ file whose import read nothing
273	    /// publishes nothing new, so its plan and recipe are the text they were.
274	    pub(crate) fn media_input(&self, media: u32) -> Value {
275	        let Some(color) = self.media(media).and_then(|m| m.color) else {
276	            return Value::Null;
277	        };
278	        let mut out = Map::new();
279	        if let Some(log) = color.log {
280	            let Some(gamut) = color.gamut.or_else(|| log.gamuts().first().copied()) else {
281	                return Value::Null;
282	            };
283	            out.insert("log".to_string(), Value::from(spelled(log)));
284	            out.insert("gamut".to_string(), Value::from(spelled(gamut)));
285	        } else if let Some(id) = color.lut {
286	            if self.media(id).is_some_and(|m| m.kind == MediaKind::Lut) {
287	                out.insert("lut".to_string(), Value::from(id));
288	            }
289	        }
290	        if let Some(peak) = color.pq.and_then(|pq| pq.effective()) {
291	            out.insert("peak".to_string(), Value::from(peak));
292	        }
293	        if out.is_empty() {
294	            Value::Null
295	        } else {
296	            Value::Object(out)
297	        }
298	    }
299	
300	    /// The media whose `color.lut` is `lut`, in list order.
301	    pub(crate) fn media_converted_by(&self, lut: u32) -> Vec<u32> {
302	        self.media
303	            .iter()
304	            .filter(|m| m.color.and_then(|color| color.lut) == Some(lut))
305	            .map(|m| m.id)
306	            .collect()
307	    }
308	}
