22	                return MediaColor(log: .appleLog, gamut: .bt2020, detected: true)
23	            }
24	            if label == Self.appleLog2Label {
25	                return MediaColor(log: .appleLog2, gamut: .appleWideGamut, detected: true)
26	            }
