31	    /// A PQ video track's HDR10 peak (spec §11 HD-12, HD-18), read when
32	    /// `probeAsset` runs: `{pq}` for a track whose description
33	    /// `InputConversion` reads as PQ — the core's reading of the
34	    /// description's mastering-display and content-light extensions, else,
35	    /// for an `av01` track, of its `av1C` record's and first sample's
36	    /// metadata OBUs, and for an `hvc1` or `hev1` track of the first sample's
37	    /// SEI (`firstSample`) — `{pq: {}}` when none reads; nil for any track
38	    /// that is not PQ. Synchronous (spec §11 W-8).
39	    static func detectedPQ(
40	        _ descriptions: [CMFormatDescription], track: AVAssetTrack, asset: AVAsset
41	    ) -> MediaColor? {
42	        guard let description = descriptions.first(where: {
43	            if case .pq = InputConversion.choose(for: $0) { return true }
44	            return false
45	        }) else { return nil }
46	        func data(_ key: CFString) -> Data? {
47	            CMFormatDescriptionGetExtension(description, extensionKey: key) as? Data
48	        }
49	        let mastering = data(kCMFormatDescriptionExtension_MasteringDisplayColorVolume)
50	        let contentLight = data(kCMFormatDescriptionExtension_ContentLightLevelInfo)
51	        if mastering == nil, contentLight == nil,
52	            CMFormatDescriptionGetMediaSubType(description) == kCMVideoCodecType_AV1
53	        {
54	            let atoms = CMFormatDescriptionGetExtension(
55	                description,
56	                extensionKey: kCMFormatDescriptionExtension_SampleDescriptionExtensionAtoms)
57	                as? [String: Any]
58	            let read = ReelHDR10.av1Peak(
59	                config: atoms?["av1C"] as? Data, sample: firstSample(of: track, in: asset))
60	            return MediaColor(pq: read)
61	        }
62	        var sample: Data?
63	        var nalLength = 0
64	        if mastering == nil, contentLight == nil, let length = hevcNALLength(description) {
65	            nalLength = length
66	            sample = firstSample(of: track, in: asset)
67	        }
68	        let read = ReelHDR10.peak(
69	            mastering: mastering, contentLight: contentLight, sample: sample, nalLength: nalLength)
70	        return MediaColor(pq: read)
